import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.CYjxsSA2.js";const k=JSON.parse('{"title":"Kali 工具箱（Docker / WSL）","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/docker.md","filePath":"advanced/docker.md"}'),d={name:"advanced/docker.md"};function s(i,t,l,n,h,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="kali-工具箱-docker-wsl" tabindex="-1">Kali 工具箱（Docker / WSL） <a class="header-anchor" href="#kali-工具箱-docker-wsl" aria-label="Permalink to &quot;Kali 工具箱（Docker / WSL）&quot;">​</a></h1><p>军团的<strong>内网攻击能力</strong>依赖工具箱 —— 军团在工具箱内执行 <code>nmap</code>、<code>nc</code> 等内网命令，武器库与主程序隔离运行。</p><p>平台提供两套工具箱，可并存：</p><table tabindex="0"><thead><tr><th>工具箱</th><th>依赖</th><th>适用</th></tr></thead><tbody><tr><td><strong>Kali Docker 工具箱</strong></td><td>Docker Desktop</td><td>容器化 Kali 武器库，隔离最彻底</td></tr><tr><td><strong>WSL 工具箱</strong></td><td>Windows WSL2</td><td>无需 Docker 的轻量替代</td></tr></tbody></table><h2 id="kali-docker-工具箱" tabindex="-1">Kali Docker 工具箱 <a class="header-anchor" href="#kali-docker-工具箱" aria-label="Permalink to &quot;Kali Docker 工具箱&quot;">​</a></h2><h3 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>已安装 <strong>Docker Desktop</strong></li><li>已获得 Kali 工具箱部署包（随发行包提供，或与 Gh0xE9 联系获取）</li></ul><h3 id="启动" tabindex="-1">启动 <a class="header-anchor" href="#启动" aria-label="Permalink to &quot;启动&quot;">​</a></h3><p>在工具箱部署包目录中执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><h3 id="在桌面端配置" tabindex="-1">在桌面端配置 <a class="header-anchor" href="#在桌面端配置" aria-label="Permalink to &quot;在桌面端配置&quot;">​</a></h3><p>打开 <strong>系统配置 → 智能体 → 执行环境 → Kali Docker 工具箱</strong>：</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>模式</strong></td><td>自动（本机缺少命令时转发到容器）/ 一律走容器 / 关闭</td></tr><tr><td><strong>容器名</strong></td><td>留空使用工具箱默认容器</td></tr><tr><td><strong>工作区挂载路径</strong></td><td>留空则使用数据目录旁的工作区</td></tr></tbody></table><p>设置页会显示实际生效的工作区；不在默认位置时，按提示调整挂载卷。</p><h3 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h3><p>设置页点**「测试连接」**，看到连通即为就绪。</p><h2 id="wsl-工具箱" tabindex="-1">WSL 工具箱 <a class="header-anchor" href="#wsl-工具箱" aria-label="Permalink to &quot;WSL 工具箱&quot;">​</a></h2><p>无需 Docker，直接使用本机 WSL2 发行版执行命令：</p><ol><li>Windows 上启用 WSL2 并安装 Ubuntu-22.04（或任选发行版）</li><li>打开 <strong>系统配置 → 智能体 → 执行环境 → WSL 工具箱</strong>，配置发行版名称、挂载根路径与模式</li><li>点**「测试连接」**验证</li></ol><h2 id="执行隔离档位" tabindex="-1">执行隔离档位 <a class="header-anchor" href="#执行隔离档位" aria-label="Permalink to &quot;执行隔离档位&quot;">​</a></h2><p>工具箱是否被使用，由<strong>执行隔离档位</strong>决定：</p><table tabindex="0"><thead><tr><th>档位</th><th>行为</th></tr></thead><tbody><tr><td><strong>不隔离</strong></td><td>命令在本机执行</td></tr><tr><td><strong>优先隔离</strong>（默认）</td><td>有可用容器 / WSL 就进隔离环境，否则本机执行</td></tr><tr><td><strong>必须隔离</strong></td><td>没有可用隔离环境即拒绝执行，不会回落本机</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">建议</p><p>装好工具箱就保持「优先隔离」；希望命令绝不碰宿主机的场景选「必须隔离」，代价是工具箱不可用时命令会直接报错。 自动模式最省心：本机没有的命令自动转发工具箱，已有的本地跑。</p></div>',23)])])}const b=a(d,[["render",s]]);export{k as __pageData,b as default};
